  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:braid-republic'), 'braid-republic', 'The Braid Republic', 'braids', 'ntinda', 'Neat parts, gentle hands and a playlist good enough for a six-hour boho. Snacks encouraged.', 'both', '08:00', '20:00', '{}'::smallint[], 10000, true, false, 'braids', '{"#2b1a4a","#7b4fd6","#f6b9a3"}'::text[], 'published', true, false, 4.9, 1284, 0),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:fade-kings'), 'fade-kings', 'Fade Kings Barbershop', 'barber', 'wandegeya', 'Fades so clean your old barber will hear about it. They''ll come to your office at lunch, too.', 'both', '07:00', '21:00', '{}'::smallint[], 10000, true, false, 'fade', '{"#141416","#3c3b48","#e0b252"}'::text[], 'published', true, false, 4.8, 2031, 1),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:silk-press-society'), 'silk-press-society', 'Silk Press Society', 'hair', 'kololo', 'Natural hair, pressed like it has somewhere important to be. Heat protection is not optional here.', 'salon', '09:00', '19:00', '{0}'::smallint[], 0, true, false, 'silk', '{"#3b1d2a","#c0587a","#ffd3c2"}'::text[], 'published', true, false, 5, 412, 2),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:locs-lattes'), 'locs-lattes', 'Locs & Lattes', 'braids', 'kololo', 'A Kisementi locs studio with a proper espresso machine. Your retwist comes with a flat white, because priorities.', 'salon', '08:00', '18:00', '{}'::smallint[], 0, true, false, 'locs', '{"#2a1d14","#8a5a3b","#f0c27a"}'::text[], 'published', false, true, 4.9, 689, 3),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:kneaded'), 'kneaded', 'Kneaded Massage & Spa', 'massage', 'muyenga', 'Certified therapists, hot towels and a view of the lake from the top of Muyenga Hill. Or at home, if the hill is too much.', 'both', '09:00', '21:00', '{}'::smallint[], 10000, true, false, 'knead', '{"#0f3b33","#2f8f78","#cde9c9"}'::text[], 'published', true, true, 4.9, 530, 4),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:polished'), 'polished', 'Polished Nail Bar', 'nails', 'nakasero', 'Gels that last longer than most group chats. Walk in tired, leave with ten tiny works of art.', 'salon', '09:00', '20:00', '{}'::smallint[], 0, true, false, 'gloss', '{"#4a1030","#e0457b","#ffd0dc"}'::text[], 'published', false, false, 4.7, 944, 5),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:fresh-fold'), 'fresh-fold', 'Fresh Fold Laundry', 'laundry', 'bukoto', 'We collect, wash, press and bring it back folded like a department store. You do literally nothing.', 'mobile', '07:00', '19:00', '{0}'::smallint[], 0, true, true, 'fold', '{"#0d2c4d","#2f7fd1","#bfe3ff"}'::text[], 'published', true, true, 4.8, 1502, 6),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:spotless'), 'spotless', 'Spotless Kampala', 'cleaning', 'naalya', 'Two-person crews, their own supplies and a strict no-shortcuts policy. They move the sofa.', 'mobile', '07:00', '18:00', '{0}'::smallint[], 0, true, false, 'shine', '{"#123a2b","#3cae84","#e3f6c8"}'::text[], 'published', false, false, 4.7, 803, 7),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:guardline'), 'guardline', 'Guardline Security', 'escort', 'kololo', 'Licensed, uniformed or plain-clothes guards from a registered security company. Calm, punctual and very hard to argue with.', 'mobile', '06:00', '22:00', '{}'::smallint[], 0, true, false, 'safe', '{"#151a22","#34465c","#9fb4cc"}'::text[], 'published', true, true, 4.8, 211, 8),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:fix-it-fred'), 'fix-it-fred', 'Fix-It Fred', 'repairs', 'kira', 'Fred and his team fix the things that have been “almost working” since last year. Call-out fee covers the first hour.', 'mobile', '08:00', '18:00', '{0}'::smallint[], 0, true, false, 'fixed', '{"#3a2408","#c8741c","#ffd88a"}'::text[], 'published', false, false, 4.6, 377, 9),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:crown-comb'), 'crown-comb', 'Crown & Comb Kids', 'hair', 'entebbe', 'A kids'' salon with cartoons, patience and stylists who can braid a moving target.', 'both', '09:00', '18:00', '{}'::smallint[], 10000, true, false, 'crowns', '{"#1d2f5a","#5a7be0","#ffe08a"}'::text[], 'published', false, true, 4.9, 268, 10),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:glow-bridal'), 'glow-bridal', 'Glow Bridal Studio', 'bridal', 'munyonyo', 'Weddings and kwanjulas, from the trial run to the last photo. Doors open at 06:00 because brides start early.', 'both', '06:00', '20:00', '{}'::smallint[], 10000, true, false, 'I do', '{"#3a2a20","#b48a6a","#f7e3cf"}'::text[], 'published', true, false, 5, 156, 11),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:cuts-curls'), 'cuts-curls', 'Cuts & Curls Mukono', 'barber', 'mukono', 'Barbers and stylists under one roof, ten minutes from Mukono taxi park.', 'salon', '08:00', '20:00', '{}'::smallint[], 0, true, false, 'curls', '{"#1f1a3a","#4a3fa0","#ff9e7a"}'::text[], 'published', false, true, 4.7, 98, 12)
