insert into public.reviews (id, business_id, rating, title, body, author_name, author_area, is_sample) values
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'review:braid-republic:Grace N.'), extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:braid-republic'), 5, 'Five hours felt like two', 'Aisha did my knotless braids at home on a Sunday. On time, neat parts, and she brought her own ring light. Next set already booked.', 'Grace N.', 'Ntinda', true),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'review:fade-kings:Daniel O.'), extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:fade-kings'), 5, 'My barber now comes to the office', 'Every second Friday at 1pm. Clean fade, no queue, and my boss thinks I have a personal stylist. Technically, I do.', 'Daniel O.', 'Kololo', true),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'review:spotless:Sharon A.'), extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:spotless'), 5, 'The kwanjula aftermath, handled', 'Two cleaners, four hours, and the house looked like 200 guests never came. Paid with Airtel Money from the sofa they had just cleaned.', 'Sharon A.', 'Kira', true),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'review:fresh-fold:Ivan M.'), extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:fresh-fold'), 5, 'My shirts have never been this confident', 'Picked up at 8, back by 6, pressed sharper than my presentation. Weighed at the gate, so no arguments about the bill.', 'Ivan M.', 'Bukoto', true),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'review:kneaded:Peace K.'), extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:kneaded'), 5, 'Ninety minutes, seven years of knots', 'Esther found knots I''d been carrying since 2019. I paid with MoMo, then had a nap I''d describe as spiritual.', 'Peace K.', 'Muyenga', true),
  (extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'review:guardline:Brian K.'), extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid, 'biz:guardline'), 5, 'A bank run with backup', 'Needed security to bank our fundraising cash. Licensed, punctual, and nobody looked twice at the bag.', 'Brian K.', 'Nakasero', true)
